99	// NewHandler builds the public HTTP surface backed by s.
100	func NewHandler(s *store.Store) http.Handler {
101		mux := http.NewServeMux()
102	
103		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
104			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
105		})
106	
107		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
108			handleRegisterDevice(s, w, r)
109		})
110		// Non-POST verbs on the exact collection path: the method-less pattern is
111		// less specific than POST above, so it only catches the rest and answers a
112		// JSON 404 instead of ServeMux's slash redirect.
113		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
114			writeError(w, http.StatusNotFound, "unknown device path")
115		})
116		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
117			writeError(w, http.StatusNotFound, "unknown session path")
118		})
119		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
120			handleCreateSession(s, w, r)
121		})
122		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
123			handleDeleteSession(s, w, r)
124		})
125		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
126			handleCreateAttachment(s, w, r)
127		})
128		mux.HandleFunc("PUT /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
129			handlePutChunk(s, w, r)
130		})
131		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/complete", func(w http.ResponseWriter, r *http.Request) {
132			handleCompleteAttachment(s, w, r)
133		})
134		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
135			handleGetAttachment(s, w, r)
136		})
137		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
138			handleGetChunk(s, w, r)
139		})
140		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
141			handleSessionChanges(s, w, r)
142		})
143		// Any other path under the new namespaces is a JSON 404 rather than
144		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
145		// Exact method-patterns above take precedence over these subtree patterns.
146		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
147			writeError(w, http.StatusNotFound, "unknown device/session path")
148		})
149		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
150			writeError(w, http.StatusNotFound, "unknown session path")
151		})
152	
153		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
154			handlePostChanges(s, w, r)
155		})
156		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
157			handleListChanges(s, w, r)
158		})
159		mux.HandleFunc("GET /v1/documents/{documentID}/changes/poll", func(w http.ResponseWriter, r *http.Request) {
160			handlePollChanges(s, w, r)
161		})
162		// Non-GET verbs on the poll path: the exact GET pattern above is more
163		// specific, so only other verbs reach this method-less pattern and get a
164		// JSON 400 instead of ServeMux's plain-text 405.
165		mux.HandleFunc("/v1/documents/{documentID}/changes/poll", func(w http.ResponseWriter, _ *http.Request) {
166			writeError(w, http.StatusBadRequest, "method is not allowed on this path")
167		})
168		mux.HandleFunc("POST /v1/documents/{documentID}/replay", func(w http.ResponseWriter, r *http.Request) {
169			handleReplay(s, w, r)
170		})
171		mux.HandleFunc("/v1/documents/{documentID}/replay", func(w http.ResponseWriter, _ *http.Request) {
172			writeError(w, http.StatusBadRequest, "method is not allowed on this path")
173		})
174		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
175			handleMergeChange(s, w, r)
176		})
177		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
178			handlePostSnapshot(s, w, r)
179		})
180		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
181			handleGetSnapshot(s, w, r)
182		})
183		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
184			handleRestore(s, w, r)
185		})
186		mux.HandleFunc("POST /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) {
187			handleSetPermission(s, w, r)
188		})
189	
190		// ServeMux treats any empty path segment (the doubled slash in
191		// /v1/documents//..., /v1/devices//sessions or
192		// /v1/sessions//documents/...) as an unclean path and answers with a 307
193		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
194		// error for an empty identifier, so intercept those paths before the mux
195		// sees them. A trailing slash empties the final id of the device/session
196		// routes and is rejected there for the same reason; the document routes
197		// keep their pre-existing ServeMux behavior.
198		return emptyIDGuard(mux)
199	}
200	
201	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
202	// JSON error instead of letting ServeMux emit its HTML redirect or a
203	// plain-text 404.
204	//
205	// The document family keeps its original rule (an empty documentID, i.e. the
206	// prefix /v1/documents//); other odd paths there retain their old response so
207	// the pre-existing surface is unchanged. The new device/session families are
208	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
209	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
210	func emptyIDGuard(next http.Handler) http.Handler {
211		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
212			p := r.URL.Path
213	
214			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
215			newFamilySegmentEmpty := false
216			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
217				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
218			}
219	
220			if documentSegmentEmpty || newFamilySegmentEmpty || malformedNewDocumentPath(p) {
221				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
222				return
223			}
224			next.ServeHTTP(w, r)
225		})
226	}
227	
228	// malformedNewDocumentPath reports whether p targets one of the new
229	// long-poll/replay endpoints but is not that endpoint's exact location: a
230	// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
231	// segment in a position short of the registered shape. ServeMux would answer
232	// those with a 301 redirect or a plain-text 404/405; the new endpoints promise
233	// a JSON error and never a redirect, so every such path is a malformed 400.
234	//
235	// Keywords are matched only past the documentID position, so documents that
236	// happen to be named "poll" or "replay" keep their ordinary merge/snapshot/
237	// changes routes.
238	func malformedNewDocumentPath(p string) bool {
239		rest, ok := strings.CutPrefix(p, "/v1/documents/")
240		if !ok {
241			return false
242		}
243		segs := strings.Split(rest, "/")
244	
245		// Poll endpoint: "poll" must be exactly the third segment, after a
246		// non-empty documentID and "changes".
247		for i, seg := range segs {
248			if seg == "poll" && i > 0 {
249				return !(len(segs) == 3 && segs[0] != "" && segs[1] == "changes")
250			}
251		}
252		// Replay endpoint: "replay" must be exactly the second segment, after a
253		// non-empty documentID.
254		for i, seg := range segs {
255			if seg == "replay" && i > 0 {
256				return !(len(segs) == 2 && segs[0] != "")
257			}
258		}
259		return false
260	}
