262	// Handler exposes the HTTP surface over a private in-memory store. Use
263	// NewHandler with a durable store for real deployments.
264	func Handler() http.Handler {
265		s, err := store.Open("")
266		if err != nil {
267			log.Fatalf("open in-memory store: %v", err)
268		}
269		return NewHandler(s)
270	}
