318	func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
319		deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty
320	
321		var req sessionRequest
322		if !decodeJSONBody(w, r, &req) {
323			return
324		}
325		if req.SessionID == "" {
326			writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
327			return
328		}
329	
330		created, err := s.CreateSession(deviceID, req.SessionID)
331		if err != nil {
332			var conflict *store.ErrSessionConflict
333			switch {
334			case errors.Is(err, store.ErrDeviceNotFound):
335				writeError(w, http.StatusNotFound, "device not found")
336			case errors.As(err, &conflict):
337				writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
338			default:
339				writeError(w, http.StatusInternalServerError, "failed to create session")
340			}
341			return
342		}
343	
344		writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
345	}
