363	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
364		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
365	
366		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
367		if err != nil || mediaType != "application/json" {
368			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
369			return
370		}
371	
372		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
373		var req postRequest
374		dec := json.NewDecoder(r.Body)
375		if err := dec.Decode(&req); err != nil {
376			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
377			return
378		}
379		// Reject trailing data after the JSON object.
380		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
381			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
382			return
383		}
384	
385		if req.DeviceID == "" {
386			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
387			return
388		}
389		if len(req.Changes) == 0 {
390			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
391			return
392		}
393	
394		changes := make([]store.Change, len(req.Changes))
395		seen := make(map[string]struct{}, len(req.Changes))
396		for i, c := range req.Changes {
397			if c.ID == "" {
398				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
399				return
400			}
401			if len(c.Payload) == 0 {
402				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
403				return
404			}
405			if _, dup := seen[c.ID]; dup {
406				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
407				return
408			}
409			seen[c.ID] = struct{}{}
410			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
411		}
412	
413		results, err := s.PostChanges(documentID, changes)
414		if err != nil {
415			var conflict *store.ErrConflict
416			if errors.As(err, &conflict) {
417				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
418				return
419			}
420			writeError(w, http.StatusInternalServerError, "failed to commit changes")
421			return
422		}
423	
424		writeJSON(w, http.StatusOK, map[string]any{"results": results})
425	}
