427	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
428		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
429	
430		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
431		if err != nil || mediaType != "application/json" {
432			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
433			return
434		}
435	
436		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
437		var req mergeRequest
438		dec := json.NewDecoder(r.Body)
439		if err := dec.Decode(&req); err != nil {
440			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
441			return
442		}
443		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
444			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
445			return
446		}
447	
448		if req.DeviceID == "" {
449			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
450			return
451		}
452		// baseCursor must be present and a non-negative integer (no fractions,
453		// strings, booleans or null).
454		if len(req.BaseCursor) == 0 {
455			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
456			return
457		}
458		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
459		if !ok {
460			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
461			return
462		}
463		if req.Change == nil {
464			writeError(w, http.StatusBadRequest, "change must be an object")
465			return
466		}
467		if req.Change.ID == "" {
468			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
469			return
470		}
471		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
472			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
473			return
474		}
475	
476		result, err := s.MergeChange(documentID, baseCursor, store.Change{
477			ID:       req.Change.ID,
478			DeviceID: req.DeviceID,
479			Payload:  req.Change.Payload,
480		})
481		if err != nil {
482			var conflict *store.ErrConflict
483			switch {
484			case errors.Is(err, store.ErrStaleCursor):
485				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
486				return
487			case errors.As(err, &conflict):
488				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
489				return
490			default:
491				writeError(w, http.StatusInternalServerError, "failed to merge change")
492				return
493			}
494		}
495	
496		writeJSON(w, http.StatusOK, result)
497	}
