499	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
500		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
501	
502		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
503		if err != nil || mediaType != "application/json" {
504			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
505			return
506		}
507	
508		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
509		var req snapshotPostRequest
510		dec := json.NewDecoder(r.Body)
511		if err := dec.Decode(&req); err != nil {
512			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
513			return
514		}
515		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
516			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
517			return
518		}
519	
520		cursor, ok := parseNonNegativeInt(req.Cursor)
521		if !ok {
522			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
523			return
524		}
525		if len(req.State) == 0 {
526			writeError(w, http.StatusBadRequest, "state is required")
527			return
528		}
529	
530		created, err := s.PutSnapshot(documentID, cursor, req.State)
531		if err != nil {
532			var conflict *store.ErrSnapshotConflict
533			switch {
534			case errors.Is(err, store.ErrSnapshotBase):
535				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
536				return
537			case errors.As(err, &conflict):
538				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
539				return
540			default:
541				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
542				return
543			}
544		}
545	
546		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
547	}
