549	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
550		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
551	
552		cursor, ok := parseCursorPath(r.PathValue("cursor"))
553		if !ok {
554			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
555			return
556		}
557	
558		state, err := s.GetSnapshot(documentID, cursor)
559		if err != nil {
560			if errors.Is(err, store.ErrSnapshotNotFound) {
561				writeError(w, http.StatusNotFound, "snapshot not found")
562				return
563			}
564			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
565			return
566		}
567	
568		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
569	}
570	
571	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
572		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
573	
574		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
575		if err != nil || mediaType != "application/json" {
576			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
577			return
578		}
579	
580		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
581		var req restoreRequest
582		dec := json.NewDecoder(r.Body)
583		if err := dec.Decode(&req); err != nil {
584			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
585			return
586		}
587		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
588			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
589			return
590		}
591	
592		if req.DeviceID == "" {
593			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
594			return
595		}
596		if req.ChangeID == "" {
597			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
598			return
599		}
600		// snapshotCursor must be present and a positive integer (no fractions,
601		// strings, booleans, null or zero).
602		if len(req.SnapshotCursor) == 0 {
603			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
604			return
605		}
606		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
607		if !ok {
608			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
609			return
610		}
611	
612		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
613		if err != nil {
614			var conflict *store.ErrRestoreConflict
615			switch {
616			case errors.Is(err, store.ErrSnapshotNotFound):
617				writeError(w, http.StatusNotFound, "snapshot not found")
618				return
619			case errors.As(err, &conflict):
620				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
621				return
622			default:
623				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
624				return
625			}
626		}
627	
628		writeJSON(w, http.StatusOK, result)
629	}
630	
631	// handleSetPermission grants or revokes a registered device's access to one
632	// document. Devices start authorized, so the first revoke is the first write;
633	// repeating the current state is idempotent (changed=false). A rejected
634	// request (bad content type, malformed JSON, trailing content, empty or
635	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
636	// unregistered device is a 404 JSON error.
637	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
638		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
639	
640		var req permissionRequest
641		if !decodeJSONBody(w, r, &req) {
642			return
643		}
644		if req.DeviceID == "" {
645			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
646			return
647		}
648		var authorized bool
649		switch req.Action {
650		case "grant":
651			authorized = true
652		case "revoke":
653			authorized = false
654		default:
655			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
656			return
657		}
658	
659		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
660		if err != nil {
661			if errors.Is(err, store.ErrDeviceNotFound) {
662				writeError(w, http.StatusNotFound, "device not found")
663				return
664			}
665			writeError(w, http.StatusInternalServerError, "failed to update permission")
666			return
667		}
668	
669		writeJSON(w, http.StatusOK, map[string]any{
670			"deviceId":   req.DeviceID,
671			"authorized": authorized,
672			"changed":    changed,
673		})
674	}
675	
676	// parseCursorPath reports whether raw is a decimal non-negative integer and
677	// returns its value. Signs, fractions and other adornments are rejected.
678	func parseCursorPath(raw string) (int64, bool) {
679		if raw == "" {
680			return 0, false
681		}
682		for _, c := range raw {
683			if c < '0' || c > '9' {
684				return 0, false
685			}
686		}
687		n, err := strconv.ParseInt(raw, 10, 64)
688		if err != nil {
689			return 0, false
690		}
691		return n, true
692	}
693	
694	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
695	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
696		var n int64
697		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
698			return 0, false
699		}
700		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
701		// require the literal to contain no fraction or exponent.
702		trimmed := strings.TrimSpace(string(raw))
703		if trimmed == "" || trimmed[0] == '-' {
704			return 0, false
705		}
706		for _, c := range trimmed {
707			if c < '0' || c > '9' {
708				return 0, false
709			}
710		}
711		return n, true
712	}
713	
714	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
715	// strings, booleans, null and negative numbers are rejected.
716	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
717		n, ok := parseNonNegativeInt(raw)
718		if !ok || n < 1 {
719			return 0, false
720		}
721		return n, true
722	}
723	
724	// isJSONObject reports whether raw decodes to a JSON object (not null, an
725	// array or a scalar).
726	func isJSONObject(raw json.RawMessage) bool {
727		var m map[string]json.RawMessage
728		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
729			return false
730		}
731		return true
732	}
733	
734	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
735		documentID := r.PathValue("documentID")
736	
737		after, limit, ok := parseChangesQuery(w, r)
738		if !ok {
739			return
740		}
741	
742		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
743		if err != nil {
744			writeError(w, http.StatusInternalServerError, "failed to list changes")
745			return
746		}
747	
748		writeChangesPage(w, changes, nextCursor)
749	}
750	
751	// handleSessionChanges is the session-scoped view of the existing change log:
752	// both path identifiers must be non-empty (the empty-segment guard rejects
753	// those before routing) and the session must currently exist, after which the
754	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
755	// the session's device has been revoked permission for the document, which is
756	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
757	// read; the change log itself is untouched.
758	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
759		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
760		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
761	
762		// Malformed query parameters are a request-shape error (400) checked
763		// before the resource lookup (404), matching the snapshot GET ordering.
764		after, limit, ok := parseChangesQuery(w, r)
765		if !ok {
766			return
767		}
768	
769		deviceID, err := s.SessionDevice(sessionID)
770		if err != nil {
771			if errors.Is(err, store.ErrSessionNotFound) {
772				writeError(w, http.StatusNotFound, "session not found")
773				return
774			}
775			writeError(w, http.StatusInternalServerError, "failed to look up session")
776			return
777		}
778	
779		authorized, err := s.DocumentAuthorized(documentID, deviceID)
780		if err != nil {
781			writeError(w, http.StatusInternalServerError, "failed to look up permission")
782			return
783		}
784		if !authorized {
785			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
786			return
787		}
788	
789		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
790		if err != nil {
791			writeError(w, http.StatusInternalServerError, "failed to list changes")
792			return
793		}
794	
795		writeChangesPage(w, changes, nextCursor)
796	}
797	
798	// parseChangesQuery parses the shared after/limit pagination parameters,
799	// writing the documented 400 on an illegal value. It is shared by the
800	// document-scoped and session-scoped change listings so their query semantics
801	// cannot drift apart.
802	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
803		q := r.URL.Query()
804	
805		after = 0
806		if raw := q.Get("after"); raw != "" {
807			v, err := strconv.ParseInt(raw, 10, 64)
808			if err != nil || v < 0 {
809				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
810				return 0, 0, false
811			}
812			after = v
813		}
814	
815		limit = defaultListLimit
816		if raw := q.Get("limit"); raw != "" {
817			v, err := strconv.ParseInt(raw, 10, 64)
818			if err != nil || v < 1 || v > maxListLimit {
819				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
820				return 0, 0, false
821			}
822			limit = v
823		}
824	
825		return after, limit, true
826	}
827	
828	// writeChangesPage renders a change listing page in the shared response shape.
829	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
830		writeJSON(w, http.StatusOK, map[string]any{
831			"changes":    changes,
832			"nextCursor": nextCursor,
833		})
834	}
835	
836	func writeJSON(w http.ResponseWriter, status int, v any) {
837		w.Header().Set("Content-Type", "application/json")
838		w.WriteHeader(status)
839		_ = json.NewEncoder(w).Encode(v)
840	}
841	
842	func writeError(w http.ResponseWriter, status int, message string) {
843		writeJSON(w, status, map[string]string{"error": message})
844	}
845	
846	// handlePollChanges is the long-polling entry over the change log.
847	//
848	// Query params share the existing change-read constraints: after is a
849	// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
850	// is 0..30000 (default 0). Rows already past after return immediately; a known
851	// document caught up to after parks until the first new commit or the wait
852	// deadline; an unknown document returns an empty page with cursor 0 at once.
853	// The response shape is the ordinary page plus a timedOut flag; a deadline
854	// expiry echoes the caller's cursor and never advances it. A client
855	// disconnect simply stops the wait and writes nothing.
856	func handlePollChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
857		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
858	
859		after, limit, ok := parseChangesQuery(w, r)
860		if !ok {
861			return
862		}
863		q := r.URL.Query()
864		var waitMs int64
865		if raw := q.Get("waitMs"); raw != "" {
866			v, err := strconv.ParseInt(raw, 10, 64)
867			if err != nil || v < 0 || v > maxPollWaitMillis {
868				writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
869				return
870			}
871			waitMs = v
872		}
873	
874		changes, nextCursor, timedOut, err := s.WaitForChanges(
875			r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
876		)
877		switch {
878		case errors.Is(err, store.ErrStoreClosing):
879			writeError(w, http.StatusServiceUnavailable, "service is shutting down")
880			return
881		case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
882			// The client went away (or, with waitMs bounded, its deadline lapsed
883			// at the transport): nothing more to write and nothing was stored.
884			return
885		case err != nil:
886			writeError(w, http.StatusInternalServerError, "failed to poll changes")
887			return
888		}
889	
890		writeJSON(w, http.StatusOK, map[string]any{
891			"changes":    changes,
892			"nextCursor": nextCursor,
893			"timedOut":   timedOut,
894		})
895	}
896	
897	// handleReplay retries an offline batch against the existing change log. The
898	// request and per-element semantics mirror POST .../changes — strict
899	// application/json body, non-empty ids, no in-batch duplicates, idempotent only
900	// when deviceId and decoded payload match, otherwise 409 reporting the
901	// conflicting id — with the registration/permission layer enforced first:
902	// 404 for an unregistered device and 403 for a revoked one, neither exposing
903	// change content. The whole batch commits in one serialized transaction that
904	// shares the document's contiguous cursor space with ordinary commits.
905	func handleReplay(s *store.Store, w http.ResponseWriter, r *http.Request) {
906		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
907	
908		var req replayRequest
909		if !decodeJSONBody(w, r, &req) {
910			return
911		}
912		if req.DeviceID == "" {
913			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
914			return
915		}
916		if req.Operations == nil {
917			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
918			return
919		}
920		if len(req.Operations) == 0 {
921			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
922			return
923		}
924	
925		changes := make([]store.Change, len(req.Operations))
926		seen := make(map[string]struct{}, len(req.Operations))
927		for i, op := range req.Operations {
928			if op.ID == "" {
929				writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
930				return
931			}
932			if len(op.Payload) == 0 {
933				writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
934				return
935			}
936			if _, dup := seen[op.ID]; dup {
937				writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
938				return
939			}
940			seen[op.ID] = struct{}{}
941			changes[i] = store.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
942		}
943	
944		results, err := s.ReplayChanges(documentID, changes)
945		if err != nil {
946			var conflict *store.ErrConflict
947			switch {
948			case errors.Is(err, store.ErrDeviceNotFound):
949				writeError(w, http.StatusNotFound, "device not found")
950			case errors.Is(err, store.ErrPermissionDenied):
951				writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
952			case errors.As(err, &conflict):
953				writeJSON(w, http.StatusConflict, map[string]string{
954					"error":      "operation id already exists with different deviceId or payload",
955					"conflictId": conflict.ID,
956				})
957			default:
958				writeError(w, http.StatusInternalServerError, "failed to replay operations")
959			}
960			return
961		}
962	
963		writeJSON(w, http.StatusOK, map[string]any{"results": results})
964	}
965

