464		if body["results"].([]any)[0].(map[string]any)["cursor"].(float64) != 2 {
465			t.Fatalf("post-grant result = %v", body["results"])
466		}
467	}
468	
469	func TestReplayConcurrentWithPosts(t *testing.T) {
470		h, _ := newTestHandler(t)
471		// Devices used by every goroutine must be registered first.
472		register := func(id string) {
473			w, _ := postJSON(t, h, "/v1/devices", map[string]string{"deviceId": id})
474			if w.Code != 200 {
475				t.Fatalf("register %s: %d %s", id, w.Code, w.Body.String())
476			}
477		}
478		register("dev")
479		register("dev2")
480	
481		const n = 20
482		var wg sync.WaitGroup
483		errs := make(chan error, 2*n)
484		for i := 0; i < n; i++ {
485			wg.Add(2)
486			go func(i int) {
487				defer wg.Done()
488				w, _ := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
489					"deviceId": "dev",
490					"changes":  []any{map[string]any{"id": fmt.Sprintf("post-%02d", i), "payload": map[string]any{"i": i}}},
491				})
492				if w.Code != 200 {
493					errs <- fmt.Errorf("post %d: %d %s", i, w.Code, w.Body.String())
494				}
495			}(i)
496			go func(i int) {
497				defer wg.Done()
498				w, _ := postJSON(t, h, "/v1/documents/doc/replay", map[string]any{
499					"deviceId":   "dev2",
500					"operations": []any{map[string]any{"id": fmt.Sprintf("replay-%02d", i), "payload": map[string]any{"i": i}}},
501				})
502				if w.Code != 200 {
503					errs <- fmt.Errorf("replay %d: %d %s", i, w.Code, w.Body.String())
504				}
505			}(i)
506		}
507		wg.Wait()
508		close(errs)
509		for err := range errs {
510			t.Error(err)
511		}
512	
513		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
514		if w.Code != 200 {
515			t.Fatal(w.Body.String())
516		}
517		if got := len(body["changes"].([]any)); got != 2*n {
518			t.Fatalf("stored %d changes, want %d", got, 2*n)
519		}
520		if body["nextCursor"].(float64) != float64(2*n) {
521			t.Fatalf("nextCursor = %v, want %d", body["nextCursor"], 2*n)
522		}
523	}
524	
525	func TestReplayPersistsAcrossRestartHTTP(t *testing.T) {
526		path := filepath.Join(t.TempDir(), "sync.db")
527		s, err := store.Open(path)
528		if err != nil {
529			t.Fatal(err)
530		}
531		h := NewHandler(s)
532	
533		w, _ := postJSON(t, h, "/v1/devices", map[string]string{"deviceId": "dev"})
534		if w.Code != 200 {
535			t.Fatal(w.Body.String())
536		}
537		w, _ = postJSON(t, h, "/v1/documents/doc/replay", map[string]any{
538			"deviceId":   "dev",
539			"operations": []any{map[string]any{"id": "o1", "payload": map[string]any{"v": 1}}},
540		})
541		if w.Code != 200 {
542			t.Fatal(w.Body.String())
543		}
544		if err := s.Close(); err != nil {
545			t.Fatal(err)
546		}
547	
548		s2, err := store.Open(path)
549		if err != nil {
550			t.Fatal(err)
551		}
552		t.Cleanup(func() { _ = s2.Close() })
553		h2 := NewHandler(s2)
554	
555		// Identical replay after restart is still idempotent at cursor 1.
556		w, body := postJSON(t, h2, "/v1/documents/doc/replay", map[string]any{
557			"deviceId":   "dev",
558			"operations": []any{map[string]any{"id": "o1", "payload": map[string]any{"v": 1.0}}},
559		})
560		if w.Code != 200 {
561			t.Fatalf("idempotent after restart = %d %s", w.Code, w.Body.String())
562		}
563		r := body["results"].([]any)[0].(map[string]any)
564		if r["created"] != false || r["cursor"].(float64) != 1 {
565			t.Fatalf("post-restart result = %v", r)
566		}
567	
568		// A poll parked on the restarted store times out at the same cursor.
569		w, body = doRequest(t, h2, http.MethodGet, "/v1/documents/doc/changes/poll?after=1&waitMs=20")
570		if w.Code != 200 || body["timedOut"] != true || body["nextCursor"].(float64) != 1 {
571			t.Fatalf("poll after restart = %d %v", w.Code, body)
572		}
573	}
