478		// baseCursor ahead -> 400.
479		w, _ = mergeBody(t, h, "doc", map[string]any{
480			"deviceId": "dev", "baseCursor": 9,
481			"change": map[string]any{"id": "cX", "payload": map[string]any{"z": 1}},
482		})
483		if w.Code != http.StatusBadRequest {
484			t.Fatalf("ahead base = %d", w.Code)
485		}
486	
487		// Same id repost -> idempotent with embedded result.
488		w, body = mergeBody(t, h, "doc", map[string]any{
489			"deviceId": "dev", "baseCursor": 1,
490			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
491		})
492		if w.Code != 200 || body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
493			t.Fatalf("idempotent = %d %v", w.Code, body)
494		}
495		res := body["result"].(map[string]any)
496		if res["id"] != "c1" || res["created"] != false || res["cursor"].(float64) != 1 {
497			t.Fatalf("embedded result = %v", res)
498		}
499	
500		// Same id, different payload -> 409.
501		w, _ = mergeBody(t, h, "doc", map[string]any{
502			"deviceId": "dev", "baseCursor": 1,
503			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 2}},
504		})
505		if w.Code != http.StatusConflict {
506			t.Fatalf("conflict = %d body=%s", w.Code, w.Body.String())
507		}
508	
509		// Seed a second object {"b":2} at cursor 2.
510		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
511			"deviceId": "dev",
512			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"b": 2}}},
513		})
514		if w.Code != 200 {
515			t.Fatal(w.Body.String())
516		}
517	
518		// Stale client at baseCursor 1 posts {"c":3}: disjoint from later {"b":2} -> merged cursor 3.
519		w, body = mergeBody(t, h, "doc", map[string]any{
520			"deviceId": "dev", "baseCursor": 1,
521			"change": map[string]any{"id": "c3", "payload": map[string]any{"c": 3}},
522		})
523		if w.Code != 200 || body["outcome"] != "merged" || body["cursor"].(float64) != 3 {
524			t.Fatalf("merged = %d %v body=%s", w.Code, body, w.Body.String())
525		}
526	
527		// Stale client posts a payload colliding with later key "b" -> 409 zero write.
528		before, _, _ := s.ListChanges("doc", 0, 100)
529		w, _ = mergeBody(t, h, "doc", map[string]any{
530			"deviceId": "dev", "baseCursor": 0,
531			"change": map[string]any{"id": "c4", "payload": map[string]any{"b": 99}},
532		})
533		if w.Code != http.StatusConflict {
534			t.Fatalf("clash = %d body=%s", w.Code, w.Body.String())
535		}
536		after, _, _ := s.ListChanges("doc", 0, 100)
537		if len(after) != len(before) {
538			t.Fatalf("conflict changed row count: before=%d after=%d", len(before), len(after))
539		}
540	}
