14	// waitResult captures one WaitForChanges outcome for the goroutine tests.
15	type waitResult struct {
16		changes  []ListedChange
17		next     int64
18		timedOut bool
19		err      error
20	}
21	
22	func waitInBackground(ctx context.Context, s *Store, doc string, after, limit int64, wait time.Duration) <-chan waitResult {
23		ch := make(chan waitResult, 1)
24		go func() {
25			changes, next, timedOut, err := s.WaitForChanges(ctx, doc, after, limit, wait)
26			ch <- waitResult{changes: changes, next: next, timedOut: timedOut, err: err}
27		}()
28		return ch
29	}
30	
31	func TestPollReturnsExistingRowsImmediately(t *testing.T) {
32		s, _ := Open("")
33		defer func() { _ = s.Close() }()
34		if _, err := s.PostChanges("doc", changes("c1", "c2")); err != nil {
35			t.Fatal(err)
36		}
37	
38		ch := waitInBackground(context.Background(), s, "doc", 0, 100, 5*time.Second)
39		select {
40		case res := <-ch:
41			if res.err != nil {
42				t.Fatalf("err = %v", res.err)
43			}
44			if len(res.changes) != 2 || res.next != 2 || res.timedOut {
45				t.Fatalf("result = %+v rows=%v", res, res.changes)
46			}
47		case <-time.After(time.Second):
48			t.Fatal("poll blocked despite existing rows")
49		}
50	}
51	
52	func TestPollUnknownDocumentReturnsImmediately(t *testing.T) {
53		s, _ := Open("")
54		defer func() { _ = s.Close() }()
55	
56		// A long wait must return at once for a document that has no rows.
57		ch := waitInBackground(context.Background(), s, "ghost", 0, 100, 30*time.Second)
58		select {
59		case res := <-ch:
60			if res.err != nil {
61				t.Fatalf("err = %v", res.err)
62			}
