// Reconnecting at any observed cursor resumes exactly there with no gap or
// duplicate.
func TestSubscribeReconnectResumes(t *testing.T) {
	h, _ := newTestHandler(t)
	srv := httptest.NewServer(h)
	defer srv.Close()
	setupSession(t, h, "dev", "sess")
	seedDoc(t, h, "doc", 4)

