	case exit := <-terminated:
		if exit != 0 {
			t.Fatalf("exit code = %d, want 0", exit)
		}
	case <-time.After(5 * time.Second):
		_ = p.cmd.Process.Kill()
		t.Fatal("process did not exit promptly after closing subscriptions")
	}

