	_ = conn2.SetReadDeadline(time.Now().Add(3 * time.Second))
	var h2 [2]byte
	if _, err := io.ReadFull(br2, h2[:]); err != nil {
		t.Fatalf("post-restart read: %v", err)
	}
	if op := h2[0] & 0x0F; op != 0x1 {
		t.Fatalf("post-restart opcode = %d, want text", op)
	}
